  window.addEventListener('keydown', e => { keys[e.key] = true; });
  window.addEventListener('keyup', e => { keys[e.key] = false; });

  // Asteroids
  const asteroids = [];
  const ASTEROID_COUNT = 5;
  const ASTEROID_MIN_SPEED = 1;
  const ASTEROID_MAX_SPEED = 3;

